const items = $input.all();
console.log(`Processing ${items.length} items.`);

// Merge All Files соединяет в строгом порядке:
// index 0: Extract from File (2023 JSON)
// index 1: Extract from File1 (2024 JSON)  
// index 2: Extract RR Content
// index 3: Extract RS Content

// Функция для безопасного извлечения текста
function extractText(item) {
  if (!item) return null;

  // Проверяем все возможные варианты
  if (typeof item.json === 'string') return item.json;
  if (item.json?.text && typeof item.json.text === 'string') return item.json.text;
  if (item.json?.data && typeof item.json.data === 'string') return item.json.data;

  // Если это объект - логируем предупреждение
  console.log('⚠️ Unexpected structure:', JSON.stringify(item.json).substring(0, 200));
  return null;
}

// Функция для безопасного извлечения JSON
function extractJSON(item) {
  if (!item) return null;
  return item.json?.data || item.json;
}

const data2023 = extractJSON(items[0]);
const data2024 = extractJSON(items[1]);
const remunerationReport = extractText(items[2]);
const remunerationSystem = extractText(items[3]);

// Детальное логирование
console.log('✅ 2023 Data:', data2023 ? 'Found' : 'NOT FOUND');
console.log('✅ 2024 Data:', data2024 ? 'Found' : 'NOT FOUND');
console.log('✅ RR:', remunerationReport ? `Found (${remunerationReport.length} chars)` : 'NOT FOUND');
console.log('✅ RS:', remunerationSystem ? `Found (${remunerationSystem.length} chars)` : 'NOT FOUND');

// Дополнительная проверка - если текст не найден, показываем структуру
if (!remunerationReport) {
  console.log('🔍 RR item structure:', JSON.stringify(items[2]).substring(0, 500));
}
if (!remunerationSystem) {
  console.log('🔍 RS item structure:', JSON.stringify(items[3]).substring(0, 500));
}

// Получаем конфигурацию
const config = $('Workflow Configuration').first().json;

// Формируем промпт для Claude
const messages = [
  {
    "role": "user",
    "content": [
      { 
        "type": "text", 
        "text": config.promptTemplate, 
        "cache_control": {"type": "ephemeral"} 
      },
      { 
        "type": "text", 
        "text": `## Remuneration Report (DOCX):\n${remunerationReport || "ERROR: RR NOT FOUND"}`,
        "cache_control": {"type": "ephemeral"} 
      },
      { 
        "type": "text", 
        "text": `## Remuneration System (DOCX):\n${remunerationSystem || "ERROR: RS NOT FOUND"}`,
        "cache_control": {"type": "ephemeral"} 
      },
      { 
        "type": "text", 
        "text": `## 2023 Data:\n${JSON.stringify(data2023, null, 2)}` 
      },
      { 
        "type": "text", 
        "text": `## 2024 Data:\n${JSON.stringify(data2024, null, 2)}\n\nPlease compare the 2023 and 2024 data.` 
      }
    ]
  }
];

return [{ 
  json: { 
    model: "claude-opus-4-5-20251101", 
    messages, 
    temperature: 0, 
    max_tokens: 12000 
  } 
}];

// Parse Claude API response and extract structured data
const items = $input.all();
const results = [];

for (const item of items) {
  const startTime = Date.now();

  // Extract the response from Claude API
  const claudeResponse = item.json.content?.[0]?.text || item.json.text || '';

  // Extract JSON from markdown code blocks if present
  let parsedData;
  const jsonMatch = claudeResponse.match(/```(?:json)?\s*([\s\S]*?)```/);

  if (jsonMatch) {
    // JSON found in code block
    try {
      parsedData = JSON.parse(jsonMatch[1].trim());
    } catch (error) {
      console.log('Error parsing JSON from code block:', error.message);
      parsedData = { error: 'Failed to parse JSON from code block', rawResponse: claudeResponse };
    }
  } else {
    // Try to parse the entire response as JSON
    try {
      parsedData = JSON.parse(claudeResponse);
    } catch (error) {
      console.log('Error parsing response as JSON:', error.message);
      parsedData = { error: 'Failed to parse response', rawResponse: claudeResponse };
    }
  }

  // Calculate metrics
  const metrics = {
    totalChanges: 0,
    uncertaintiesCount: 0,
    dataQualityIssuesCount: 0,
    processingTimeMs: Date.now() - startTime
  };

  // Count changes if data structure exists
  if (parsedData.changes && Array.isArray(parsedData.changes)) {
    metrics.totalChanges = parsedData.changes.length;
  }

  // Count uncertainties
  if (parsedData.uncertainties && Array.isArray(parsedData.uncertainties)) {
    metrics.uncertaintiesCount = parsedData.uncertainties.length;
  }

  // Count data quality issues
  if (parsedData.dataQualityIssues && Array.isArray(parsedData.dataQualityIssues)) {
    metrics.dataQualityIssuesCount = parsedData.dataQualityIssues.length;
  }

  // Combine parsed data with metrics
  results.push({
    json: {
      ...parsedData,
      metrics: metrics,
      processedAt: new Date().toISOString()
    }
  });
}

return results;
